import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IArticleFilterModel, ArticleFilterModel } from 'src/app/data/model/article/ArticleFilterModel';
import { ArticleService } from 'src/app/data/service/article/article.service';
import { AddOrUpdateArticleTagModel, ArticleTagModel, IArticleTagModel } from '../../../../../data/model/article/ArticleModel';

@Component({
  selector: 'app-article-tag',
  templateUrl: './article-tag.component.html',
  styleUrls: ['./article-tag.component.scss']
})
export class ArticleTagComponent implements OnInit {

  selectedArticleId = 0;
  filteredArticles: IArticleFilterModel;
  isSelected = false;
  selectedCategory = 'add';
  searchTitle = '';
  addList: string[] = [];
  editList: IArticleTagModel[] = [];
  tagName = '';
  form: FormGroup;

  constructor(
    private fb: FormBuilder,
    private articleService: ArticleService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private activatedRoute: ActivatedRoute,
    private router: Router,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      id: ['', [Validators.required, Validators.min(1)]],
      tag: ['', [Validators.required, Validators.minLength(2), Validators.maxLength(2000)]]
    });

    let filter: IArticleFilterModel;

    this.activatedRoute.queryParams.subscribe(params => {

      const page = params.page ? params.page : 1;
      const take = params.take ? params.take : 12;
      const title = params.title ? params.title : null;

      filter = new ArticleFilterModel(page, take, title);

      this.filteredArticles = filter;

      SharedIonic.loading(this.loadingController);

      this.articleService.GetAdminArticlesByFilter(filter).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (res.status === GResponse.SuccessStatus) {
            this.filteredArticles = res.data;
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    });
  }

  onTagSelected(index: string | number) {

    let model: IArticleTagModel = this.editList[index];

    this.form.setValue({
      id: model.id,
      tag: model.name
    });
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به درج هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAddTags();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdateTags();
          }
        }
      ]
    });

    await alert.present();
  }

  onRemoveEditTag(index: string | number) {

    let model: IArticleTagModel = this.editList[index];

    SharedIonic.loading(this.loadingController);

    this.articleService.RemoveArticleTag(model.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.getTagsByArticleId(this.selectedArticleId);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onCancel() {
    this.isSelected = false;

    this.addList = [];
    this.editList = [];
    this.tagName = '';
  }

  onAddTag() {

    if (this.tagName === '') {

      return;
    }

    this.addList.push(this.tagName);
    this.tagName = '';
  }

  onUpdateTags() {

    if (!this.form.valid) {
      return;
    }

    let list: IArticleTagModel[] = [];

    this.editList.forEach(tag => {
      if (+this.form.value.id === +tag.id) {
        list.push(new ArticleTagModel(tag.id, this.form.value.tag));
      } else {
        list.push(new ArticleTagModel(tag.id, tag.name));
      }
    });

    SharedIonic.loading(this.loadingController);

    this.articleService.AddOrUpdateArticleTag(
      new AddOrUpdateArticleTagModel(this.selectedArticleId, list)
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.tagName = '';
          this.addList = [];
          list = [];
          this.getTagsByArticleId(this.selectedArticleId);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onAddTags() {

    if (this.addList.length === 0) {

      return;
    }

    let list: IArticleTagModel[] = [];

    this.addList.forEach(tag => {
      list.push(new ArticleTagModel(0, tag));
    });

    SharedIonic.loading(this.loadingController);

    this.articleService.AddOrUpdateArticleTag(
      new AddOrUpdateArticleTagModel(this.selectedArticleId, list)
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.tagName = '';
          this.addList = [];
          list = [];
          this.getTagsByArticleId(this.selectedArticleId);
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onRemoveAddTag(index: number | string) {

    this.addList.splice(+index, 1);
  }

  MakePageCountArray(pageCount: number | string): Array<number | string> {

    const array: string[] = [];

    for (let i = 1; i <= pageCount; i++) {

      array.push(i.toString());
    }

    return array;
  }

  goPreviousPage() {

    if (this.filteredArticles.startPage == null) {
      return;
    }
    if (this.filteredArticles.pageId > this.filteredArticles.startPage && +this.filteredArticles.pageId - 1 > 0) {
      this.setQueryParams(+this.filteredArticles.pageId - 1);
    }
  }

  goNextPage() {

    if (this.filteredArticles.endPage == null) {
      return;
    }
    if (this.filteredArticles.pageId < this.filteredArticles.endPage) {
      this.setQueryParams(+this.filteredArticles.pageId + 1);
    }
  }

  goPage(pageId: number | string) {
    this.setQueryParams(+pageId);
  }

  setQueryParams(pageId: number) {

    this.filteredArticles.title = this.searchTitle;

    this.router
      .navigate(
        ['AdminPanel', 'ArticleTag'],
        {
          queryParams:
          {
            page: pageId < 1 ? 1 : pageId,
            take: this.filteredArticles.takeEntity ? this.filteredArticles.takeEntity : null,
            title: this.filteredArticles.title ? this.filteredArticles.title : null
          }
        });
  }

  onDelete(): void {

    // SharedIonic.loading(this.loadingController);

    // this.articleService.DeleteArticleById(+this.selectedArticleId).subscribe(
    //   res => {
    //     SharedIonic.dismissLoading(this.loadingController);
    //     if (GResponse.SuccessStatus === res.status) {
    //       SharedIonic.successToast(this.toastController);
    //       this.setQueryParams(1);
    //     } else {
    //       SharedIonic.unSuccessToast(this.toastController);
    //     }
    //   },
    //   err => {
    //     SharedIonic.dismissLoading(this.loadingController);
    //     SharedIonic.unSuccessToast(this.toastController);
    //   }
    // );
  }

  async presentAlertConfirm(index: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemoveAddTag(index);
          }
        }
      ]
    });

    await alert.present();
  }

  async presentRemoveAlertConfirm(index: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemoveEditTag(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onSelectItem(id: string | number) {

    this.selectedArticleId = +id;
    this.isSelected = true;

    this.getTagsByArticleId(id);
  }

  getTagsByArticleId(id: string | number) {

    SharedIonic.loading(this.loadingController);

    this.articleService.GetArticleTags(+id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.editList = res.data;
          this.form.setValue({
            id: 0,
            tag: ''
          });
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }
}
